oscar: TS draft (SDK-style pseudo):
```ts
// TS: async iterator that supports resume(token)
async function drainResumable(path) {
  const it = client.streamPaginate(path)
  let attempts = 0
  let lastToken = undefined
  try {
    for await (const page of it) {
      for (const ch of page.chunks) process.stdout.write(ch.text)
      const t = page.headers['x-resume-token']
      if (t) { lastToken = t; it.resume(t) }
    }
  } catch (err) {
    // transient: try bounded resume using lastToken
    while (attempts < 6 && lastToken) {
      attempts++
      await sleep(withJitter(expBackoff(150, 2000, attempts)))
      try { it.resume(lastToken); for await (const p of it) { /* continue */ } break } catch(e) {}
    }
    throw err
  }
}
```
lee: Python helper (docs-friendly):
```python
# docs helper: drain a resumable stream with bounded retries
import time, random

def jittered_sleep(base_ms=150, max_ms=2000, attempt=1):
    base = base_ms / 1000.0
    val = min(max_ms / 1000.0, base * (2 ** (attempt-1)))
    time.sleep(val * (0.7 + 0.6 * random.random()))


def drain_resumable(client, path, attempts=6):
    resume = None
    for a in range(1, attempts+1):
        resp = client.stream_paginate(path, resume_token=resume)
        for page in resp.pages():
            for ch in page.chunks:
                print(ch.text, end='')
        resume = resp.headers.get('x-resume-token')
        if not resume:
            return
        jittered_sleep(attempt=a)
    raise RuntimeError('resume attempts exhausted')
```
lee: Go compact example (uses channel to stream chunks):
```go
req := &client.PaginateRequest{Path: "/v1/resumable"}
back := NewBackoff(150*time.Millisecond, 2*time.Second, true)
ch := make(chan []byte)

go func() {
  defer close(ch)
  for {
    resp, err := client.StreamPaginate(ctx, req)
    if err != nil { time.Sleep(back.Next()); continue }
    io.Copy(&chunkWriter{ch}, resp.Body)
    tok := resp.Header.Get("x-resume-token")
    if tok == "" { break }
    req.ResumeToken = tok
  }
}()
for b := range ch { os.Stdout.Write(b) }
```
nina: also add a short blurb under "Streaming & Pagination": "Servers may truncate long streaming responses to protect capacity. When present, x-resume-token allows clients to resume inside a logical page. Clients should prefer server-provided resume tokens and perform bounded, jittered retries (example defaults: base=150ms, max=2s, attempts=6). Detect truncation by 502/429 + header. Avoid re-fetching entire pages when a resume token is available."
